      "title": "科学家发现反离子限域传质新机制",
      "summary": "首页 > 科研进展 近日，中国科学技术大学团队在离子限域传质领域取得进展。研究 发现反离子限域诱导的电荷反转效应，实现了荷正电亚纳米通道对阳离子的选择性传递 ，建立了反离子限域离子传质新范式。 纳米限域通道中的离子传递是分离、能源和纳米流体学的基础。现有离子选择性调控策略，往往忽视了反离子调控的影响。 研究团队精准 设",
